using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using Newtonsoft.Json.Linq;
using UnityEngine;

namespace DungeonContract.Editor
{
    public static class DcP3Checks
    {
        private static JObject parameters;
        private static JObject geometry;
        private static readonly List<string> passed=new List<string>();
        private static DcP1World World(int count=2)=>new DcP1World(new JObject{["parameters"]=parameters,["p1_world"]=geometry,["practice"]=false,["weapon_stage"]=true,["p2_stage"]=true,["p3_stage"]=true,["seed"]=20261012,["run_id"]="p3_model",["members"]=new JArray(Enumerable.Range(0,count).Select(index=>new JObject{["player_id"]=(index+1).ToString(),["slot"]=index,["loadout_id"]=index%2==0?"ranger":"runesmith"}))});
        private static void Require(bool value,string name){if(!value)throw new InvalidOperationException("P3 "+name);}
        private static void Case(string name,Action check){check();passed.Add(name);}
        private static DcP1Input Intent(DcP1World world,string id,bool interact=true)=>new DcP1Input{Sequence=1,WeaponID=world.ActiveWeapon(id),WeaponRevision=world.WeaponRevision(id),Interact=interact};
        private static void Down(DcP1World world,int index,long until=20000){var state=world.Capture();state["players"][index]["Health"]=0;state["players"][index]["Life"]="downed";state["players"][index]["Knockdowns"]=1;state["players"][index]["DownedGeneration"]=1;state["players"][index]["DownedUntil"]=until;world.Restore(state);}
        public static void Regression(){DcP1Checks.Run();DcS1Checks.Run();DcS2Checks.Run();DcP21Checks.Run();DcP2MultiplayerChecks.Run();Run();}
        public static void Run()
        {
            parameters=JObject.Parse(File.ReadAllText(Path.GetFullPath("../../docs/game-demo/config/parameters-v4-p2-1.json")));geometry=JObject.Parse(File.ReadAllText(Path.GetFullPath("../../docs/game-demo/config/world-v4-p2-1.json")));passed.Clear();
            Case("rescue completes after three seconds without spending budget",()=>{var world=World();Down(world,1);for(var frame=0;frame<=92;frame++){world.Input("1",Intent(world,"1"));world.Tick(frame*33);}var snapshot=world.Snapshot();Require((int)snapshot["players"][1]["health"]==30&&(string)snapshot["players"][1]["life_state"]=="alive"&&(int)snapshot["players"][0]["rescues"]==1&&(int)snapshot["reinforcement_remaining"]==3,"rescue");});
            Case("release cancels rescue and restarts full duration",()=>{var world=World();Down(world,1);for(var frame=0;frame<50;frame++){world.Input("1",Intent(world,"1"));world.Tick(frame*33);}world.Input("1",Intent(world,"1",false));world.Tick(1650);world.Input("1",Intent(world,"1"));world.Tick(1683);Require((long)world.Snapshot()["players"][0]["rescue_remaining_ms"]==3000,"partial rescue retained");});
            Case("disconnect cancels rescue without healing",()=>{var world=World();Down(world,1);world.Input("1",Intent(world,"1"));world.Tick(33);world.Presence("1",false);world.Tick(66);Require((int)world.Snapshot()["players"][1]["health"]==0&&(long)world.Snapshot()["players"][0]["rescue_remaining_ms"]==0,"disconnect rescue");});
            Case("all down without recovery ends immediately",()=>{var world=World();Down(world,0);Down(world,1);var state=world.Capture();state["budget"]=0;world.Restore(state);var facts=world.Tick(33);Require(world.Terminal&&(string)world.Snapshot()["reason"]=="team_wipe"&&facts.Count(item=>(string)item["kind"]=="death")==2,"wipe");});
            Case("downed timeout emits actual death once",()=>{var world=World();Down(world,1);Require(world.Tick(20000).Count(item=>(string)item["kind"]=="death")==1,"missing death");Require(world.Tick(20033).All(item=>(string)item["kind"]!="death"),"duplicate death");});
            Case("reinforcement requires Go reservation and landing acknowledgement",()=>{var world=World();Down(world,1);world.Tick(20000);var receipt=new JObject{["reinforcements"]=new JObject{["reinforce_model"]=new JObject{["player_id"]="2",["status"]="pending_spawn"}}};world.Acknowledge(receipt);var facts=world.Tick(23000);Require(facts.Any(item=>(string)item["kind"]=="reinforcement_spawned")&&(int)world.Snapshot()["players"][1]["health"]==0,"unconfirmed healing");receipt["reinforcements"]["reinforce_model"]["status"]="spawned";world.Acknowledge(receipt);world.Acknowledge(receipt);Require((int)world.Snapshot()["players"][1]["health"]==100&&(long)world.Snapshot()["players"][1]["life_generation"]==2,"duplicate spawn");});
            Case("rescue preserves equipment ammunition and cooldowns",()=>{var world=World();Down(world,1);var state=world.Capture();state["players"][1]["MeleeEquipped"]=true;state["players"][1]["Magazine"]=2;state["players"][1]["AbilityAt"]=12000;world.Restore(state);for(var frame=0;frame<=92;frame++){world.Input("1",Intent(world,"1"));world.Tick(frame*33);}var player=world.Snapshot()["players"][1];Require((bool)player["melee_equipped"]&&(int)player["magazine"]==2&&(long)player["ability_remaining_ms"]>8000,"resource reset");});
            Case("rescue cannot operate through intact cover",()=>{var world=World();Down(world,1);var state=world.Capture();state["players"][0]["Position"]=new JObject{["x"]=8.4,["y"]=6};state["players"][1]["Position"]=new JObject{["x"]=9.6,["y"]=6};state["covers"]=new JArray(new JObject{["ID"]="rescue_cover",["Room"]=0,["Position"]=new JObject{["x"]=9,["y"]=6},["Health"]=60});world.Restore(state);for(var frame=0;frame<=92;frame++){world.Input("1",Intent(world,"1"));world.Tick(frame*33);}Require((int)world.Snapshot()["players"][1]["health"]==0&&(long)world.Snapshot()["players"][0]["rescue_remaining_ms"]==0,"wall rescue");});
            Case("real shield damage interrupts current rescue",()=>{var world=World();Down(world,1);world.Input("1",Intent(world,"1"));world.Tick(0);var state=world.Capture();state["players"][0]["Shield"]=20;state["players"][0]["ShieldUntil"]=10000;state["projectiles"]=new JArray(new JObject{["ID"]="hostile_rescue",["Action"]="hostile_attack",["Owner"]="archer",["Room"]=0,["Position"]=state["players"][0]["Position"].DeepClone(),["Direction"]=new JObject{["x"]=1,["y"]=0},["Damage"]=12,["Speed"]=1,["Enemy"]=true,["Unbounded"]=true});world.Restore(state);world.Input("1",Intent(world,"1"));world.Tick(33);Require((int)world.Snapshot()["players"][0]["health"]==100&&(int)world.Snapshot()["players"][0]["shield"]==8&&(long)world.Snapshot()["players"][0]["rescue_remaining_ms"]==0,"shield failed to interrupt");});
            Case("control fence replay preserves confirmed prefix and drops departed intent",()=>{var world=World();var holder=new GameObject("P3 replay model");try{var runtime=holder.AddComponent<DcP0V3>();var flags=BindingFlags.Instance|BindingFlags.NonPublic;typeof(DcP0V3).GetField("p1World",flags).SetValue(runtime,world);var tick=typeof(DcP0V3).GetMethod("TickP3",flags);for(var frame=1;frame<=12;frame++){if(frame==9){var action=Intent(world,"1",false);action.ActionSequence=1;world.QueueAction("1","attack_press",action,"unconfirmed_attack");}world.QueueFoundationInput("1",Intent(world,"1",false));tick.Invoke(runtime,new object[]{frame*100L,frame*100L});}typeof(DcP0V3).GetField("p3ConfirmedTick",flags).SetValue(runtime,8L);var left=(HashSet<string>)typeof(DcP0V3).GetField("p3Left",flags).GetValue(runtime);left.Add("1");typeof(DcP0V3).GetMethod("RebaseP3",flags).Invoke(runtime,null);Require((bool)world.Snapshot()["players"][0]["left"]&&world.WorldTick==12&&(int)world.Snapshot()["players"][0]["magazine"]==8,"rebase failed");}finally{UnityEngine.Object.DestroyImmediate(holder);}});
            Case("world checkpoint restores pending reliable action dedup",()=>{var world=World();var input=Intent(world,"1",false);input.ActionSequence=1;world.QueueAction("1","ability_primary",input,"stable_action");var checkpoint=world.Capture();world.Tick(33);var expected=world.Snapshot();world.Restore(checkpoint);world.Tick(33);Require(JToken.DeepEquals(expected,world.Snapshot()),"unconfirmed suffix replay");});
            Case("P3 runtime snapshot matches recovery snapshot",()=>{var world=World(4);Down(world,1);world.Tick(33);var expected=JObject.Parse(world.Snapshot().ToString());var actual=JObject.Parse(world.RuntimeSnapshot().ToString());Require(JToken.DeepEquals(expected,actual),"baseline parity "+string.Join(",",expected.Properties().Where(item=>!JToken.DeepEquals(item.Value,actual[item.Name])).Select(item=>item.Name)));});
            Case("dynamic at or before baseline cannot change frozen coordinates",()=>{var value=World().Snapshot();value["players"][0]["x"]=2.18446183f;var replica=new DcS1Replica();replica.Baseline(value,"1",1);foreach(var packet in DcS1Replica.Encode((JObject)value.DeepClone(),1,2,3))Require(!replica.Dynamic(packet,2,3),"same frame overwrote baseline");Require((float)replica.Snapshot["players"][0]["x"]==2.18446183f,"precision changed");});
            Case("Boss death succeeds without waiting for summon queue",()=>{var world=World(1);var state=world.Capture();state["players"][0]["Room"]=5;state["players"][0]["Position"]=new JObject{["x"]=10,["y"]=10};for(var index=0;index<5;index++)state["rooms"][index]["Status"]="cleared";state["rooms"][5]["Status"]="active";state["rooms"][5]["Wave"]=1;state["rooms"][5]["Pending"]=new JArray("guard");state["enemies"]=new JArray(new JObject{["ID"]="boss",["Kind"]="boss",["Room"]=5,["Position"]=new JObject{["x"]=11,["y"]=10},["Health"]=1,["Maximum"]=1,["AttackAt"]=10000,["ReadyAt"]=10000});world.Restore(state);world.Action("1","attack_press",Intent(world,"1",false));var facts=new List<JObject>();for(var frame=0;frame<5&&!world.Terminal;frame++)facts.AddRange(world.Tick(frame*33));Require(world.Outcome=="success"&&facts.Any(item=>(string)item["kind"]=="kill"&&(string)item["target_id"]=="boss"),"waited for summons");});
            File.WriteAllText((DcBootstrap.DemoEvidenceRoot+"/")+(DcV6Profile.Active?"v6-regression-":"")+"p3-model.json",new JObject{["scope"]="P3_model_modified_state_fixtures",["passed"]=passed.Count,["cases"]=new JArray(passed),["real_udp"]=false,["real_storage"]=false,["human"]=false}.ToString());Debug.Log("DC P3 model passed "+passed.Count);
        }
    }
}
